const COMMON_FACTS=(level,age,grade,content,aime)=>[
  {icon:'📝',title:T('题型','Format','形式'),body:T('25 道选择题，每题 A–E 五个选项，只有一个正确；限时 75 分钟。','25 multiple-choice questions, each with five choices A–E and exactly one correct answer, in 75 minutes.','25 問の選択問題。各問 A〜E の5つの選択肢から正解は1つ。試験時間 75 分。')},
  {icon:'🎯',title:T('计分','Scoring','配点'),body:T('答对 6 分，留空 1.5 分，答错 0 分，满分 150。随便猜的期望（1.2 分）低于留空。','6 points for a correct answer, 1.5 for a blank, 0 for a wrong answer; maximum 150. A blind guess is worth 1.2 points on average — less than leaving it blank.','正解 6 点・無回答 1.5 点・不正解 0 点、満点 150 点。あてずっぽうの期待値（1.2 点）は無回答より低い。')},
  {icon:'🎓',title:T('参赛资格','Who can take it','受験資格'),body:T(`${grade.zh}，且考试当天年龄不超过 ${age} 岁（以 MAA 规则为准）。`,`${grade.en}, and ${age} years old or younger on the competition day (see MAA rules).`,`${grade.ja}、かつ試験日に ${age} 歳以下（MAA の規則による）。`)},
  {icon:'📅',title:T('2026 年日期','2026 dates','2026 年の日程'),body:T(`AMC ${level}A：2026 年 11 月 5 日（周四）；AMC ${level}B：11 月 13 日（周五）（美国东部时间）。中国、日本等地区的时间由当地组织方决定，见“报名指南”。A、B 两场都可以参加，但同一天不能同时考 AMC 10 和 AMC 12。`,`AMC ${level}A: Thu Nov 5, 2026; AMC ${level}B: Fri Nov 13, 2026 (US Eastern). Local times in China, Japan and elsewhere are set by the regional organizer — see the Registration tab. You may take both A and B, but not AMC 10 and AMC 12 on the same day.`,`AMC ${level}A：2026年11月5日（木）、AMC ${level}B：11月13日（金）（米国東部時間）。中国・日本などの時間は各地域の主催団体が決めます（「申し込み」タブ参照）。A と B の両方を受けられますが、同じ日に AMC 10 と AMC 12 は受けられません。`)},
  {icon:'📚',title:T('考试内容','What it covers','出題範囲'),body:content},
  {icon:'🏆',title:T('下一步：AIME','Next step: AIME','つぎのステップ：AIME'),body:aime}
];

